// ============================================================
// n8n Code Node — "Merge Report Fragments"
// Replaces the AI-based merge step entirely. Deterministic, 
// no LLM call, no risk of summarization/regeneration loss.
// ============================================================

const fragmentA = $('Generate Report with AI').item.json.output;  // <-- adjust node name
const fragmentB = $json.output;

// ---------- STRATEGY 1: Overlap detection (preferred) ----------
// Handles the common case: B re-sends the same content A was cut off in,
// then continues further. Finds the longest verbatim suffix-of-A / 
// prefix-of-B match and splices there — zero content loss, zero duplication.
function findOverlap(a, b, maxCheck = 3000, minOverlap = 15) {
  const checkLen = Math.min(a.length, b.length, maxCheck);
  for (let len = checkLen; len > minOverlap; len--) {
    if (a.slice(-len) === b.slice(0, len)) {
      return len;
    }
  }
  return 0;
}

// ---------- STRATEGY 1b: Whitespace-tolerant overlap ----------
// Same idea as Strategy 1, but n8n/LLM outputs frequently differ in 
// trailing/leading whitespace at the exact seam (e.g. A ends with no 
// trailing newline, B starts with "\n\n" before the same word). A strict 
// byte-for-byte match misses this even though the content clearly overlaps.
// This strips whitespace from the edges being compared, finds the overlap 
// on the trimmed text, then maps the cut point back to the ORIGINAL 
// (untrimmed) strings so no real content is lost.
function findOverlapTrimmed(a, b, maxCheck = 3000, minOverlap = 10) {
  const aTrimmedEnd = a.replace(/\s+$/, '');      // a with trailing whitespace removed
  const bTrimmedStart = b.replace(/^\s+/, '');     // b with leading whitespace removed
  const leadingWsLenB = b.length - bTrimmedStart.length;

  const checkLen = Math.min(aTrimmedEnd.length, bTrimmedStart.length, maxCheck);
  for (let len = checkLen; len > minOverlap; len--) {
    if (aTrimmedEnd.slice(-len) === bTrimmedStart.slice(0, len)) {
      // Found overlap on trimmed text. A is cut BEFORE the overlapping 
      // text (so the overlap itself is dropped from A's side); B must 
      // resume FROM THE START of the overlap (not after it), since B's 
      // copy is what actually supplies that text in the merged output.
      const aCutIndex = aTrimmedEnd.length - len;
      const bResumeIndex = leadingWsLenB; // start of B's trimmed content = start of the overlap
      return { overlapLen: len, aCutIndex, bResumeIndex, leadingWsLenB };
    }
  }
  return null;
}

// ---------- STRATEGY 2: Structural splice fallback ----------
// Used only when no overlap exists. Cuts A at its last complete </table> 
// (a guaranteed-safe boundary — never mid-tag/mid-table), then searches 
// for a long (200+ char), UNIQUE anchor of A's post-cut text inside B to 
// find the correct resume point. Reports with repeating structure (e.g. 
// multiple origins sharing identical section headers) make short anchors 
// unreliable, so short/ambiguous matches are deliberately rejected rather 
// than guessed.
function findSafeBoundaryInA(a) {
  const lastTable = a.lastIndexOf('</table>');
  return lastTable !== -1 ? lastTable + '</table>'.length : 0;
}

function findAnchorInB(a, cutAt, b) {
  const afterCut = a.slice(cutAt, cutAt + 800).trim();
  if (!afterCut) return { idx: -1, ambiguous: false };

  const MIN_TRUSTED_ANCHOR = 200;
  for (let len = Math.min(800, afterCut.length); len >= MIN_TRUSTED_ANCHOR; len -= 20) {
    const anchor = afterCut.slice(0, len);
    const firstIdx = b.indexOf(anchor);
    if (firstIdx === -1) continue;
    const secondIdx = b.indexOf(anchor, firstIdx + 1);
    if (secondIdx === -1) {
      return { idx: firstIdx, ambiguous: false };
    }
  }
  return { idx: -1, ambiguous: true };
}

function mergeFragments(a, b) {
  // ---------- STRATEGY 0: Identity check ----------
  // If both fragments are identical (the AI passed the report through 
  // unchanged because it was already complete), return one copy as-is.
  if (a === b) {
    return {
      merged: a,
      strategy: 'identical-passthrough',
      ok: true,
      detail: 'Fragments are identical — returned one copy unchanged'
    };
  }

  // Also catch near-identical with only whitespace differences
  if (a.trim() === b.trim()) {
    return {
      merged: a.trim(),
      strategy: 'identical-passthrough-trimmed',
      ok: true,
      detail: 'Fragments identical after trimming — returned one copy unchanged'
    };
  }

  const overlap = findOverlap(a, b);
  if (overlap > 0) {
    return {
      merged: a.slice(0, -overlap) + b,
      strategy: 'overlap',
      ok: true,
      detail: `${overlap} chars overlap removed`
    };
  }

  // Strict match failed — try whitespace-tolerant overlap before giving up.
  const trimmedMatch = findOverlapTrimmed(a, b);
  if (trimmedMatch) {
    const cleanA = a.slice(0, trimmedMatch.aCutIndex);
    const cleanB = b.slice(trimmedMatch.bResumeIndex);
    return {
      merged: cleanA + cleanB,
      strategy: 'overlap-whitespace-tolerant',
      ok: true,
      detail: `${trimmedMatch.overlapLen} chars overlap removed ` +
              `(ignoring ${trimmedMatch.leadingWsLenB} leading whitespace chars in B)`
    };
  }

  // ---------- STRATEGY 3: Broken-tag trim + direct concat ----------
  // Handles the case where A was cut off mid-tag (e.g. "<hr class" with 
  // no closing ">") and B is a clean continuation — no overlap at all, 
  // just a broken dangling tag at the end of A that needs removing.
  // Detection: if everything after A's last ">" is only whitespace + 
  // start of an incomplete tag (contains "<" but no closing ">"), we can 
  // safely strip it and concatenate B directly.
  const lastGt = a.lastIndexOf('>');
  if (lastGt !== -1) {
    const trailingJunk = a.slice(lastGt + 1);
    const isIncompleteTag = trailingJunk.includes('<') && !trailingJunk.includes('>');
    const isWhitespaceOnly = trailingJunk.trim() === '';
    if (isIncompleteTag || isWhitespaceOnly) {
      const cleanA = a.slice(0, lastGt + 1);
      return {
        merged: cleanA + '\n' + b,
        strategy: 'broken-tag-trim',
        ok: true,
        detail: `Stripped broken trailing content from A: ${JSON.stringify(trailingJunk.trim().slice(0, 60))}, then appended B directly`
      };
    }

    // ---------- STRATEGY 3b: Mid-content truncation ----------
    // Handles the case where A was cut off mid-text-content after a valid
    // closing tag — e.g. mid-HTML-entity ("&midd" where B starts with "ot;"),
    // mid-word, or mid-number inside element text. The trailing junk has no 
    // '<' (so it's not a broken tag) and is not whitespace-only (so Strategy 3
    // doesn't fire), but B correctly continues the same text stream.
    // Detection: trailing content after last '>' is short plain text (no tags),
    // and B's start either: (a) begins with the completion of a broken entity
    // pattern, or (b) the trailing text + B start together form a recognizable 
    // pattern (entity, word, number).
    // Safe heuristic: if trailingJunk is ≤80 chars of plain text with no tags,
    // check if B starts with content that could plausibly continue it. We do 
    // this by checking if (trailingJunk + b's first ~100 chars) parses cleanly,
    // specifically by verifying the seam produces no broken HTML entity.
    const isShortPlainText = trailingJunk.length <= 80 && 
                             !trailingJunk.includes('<') && 
                             !trailingJunk.includes('>') &&
                             trailingJunk.trim().length > 0;
    if (isShortPlainText) {
      // Check for broken HTML entity: trailingJunk ends with partial &xxx
      const brokenEntityMatch = trailingJunk.match(/&[a-zA-Z#0-9]{0,8}$/);
      if (brokenEntityMatch) {
        // B should start with the entity completion — just concat
        return {
          merged: a + b,
          strategy: 'broken-entity-concat',
          ok: true,
          detail: `A cut off mid-entity (${JSON.stringify(trailingJunk.trim().slice(-20))}), B continues directly`
        };
      }
      // More general: any short plain-text tail after last '>' — concat directly
      // since B is a continuation of the same text node
      return {
        merged: a + b,
        strategy: 'mid-content-concat',
        ok: true,
        detail: `A cut off mid-content after last tag (${JSON.stringify(trailingJunk.trim().slice(0, 40))}), B continues directly`
      };
    }
  }

  const cutAt = findSafeBoundaryInA(a);
  const { idx: resumeAt, ambiguous } = findAnchorInB(a, cutAt, b);

  if (resumeAt === -1) {
    const reason = ambiguous
      ? 'Anchor text matched multiple locations in B — too ambiguous to auto-resolve safely'
      : 'No overlap or anchor match found between fragments';
    return {
      merged: a + `\n\n<!-- MERGE WARNING: ${reason}. Fragment B appended as-is below — manual review required. -->\n\n` + b,
      strategy: 'unsafe-concat',
      ok: false,
      detail: reason
    };
  }

  const cleanA = a.slice(0, cutAt);
  const cleanB = b.slice(resumeAt);
  return {
    merged: cleanA + '\n\n' + cleanB,
    strategy: 'structural-splice',
    ok: true,
    detail: `cut A at table-end (pos ${cutAt}), resumed B at unique anchor match (pos ${resumeAt})`
  };
}

// ---------- Run merge ----------
const result = mergeFragments(fragmentA, fragmentB);

// ---------- Post-merge validation & auto-repair ----------
function tagBalance(html, tag) {
  const opens = (html.match(new RegExp(`<${tag}(?:\\s[^>]*)?>`, 'g')) || []).length;
  const closes = (html.match(new RegExp(`</${tag}>`, 'g')) || []).length;
  return { opens, closes, diff: opens - closes, balanced: opens === closes };
}

if (!result.ok) {
  throw new Error(
    `MERGE FAILED — manual review required. Reason: ${result.detail}. ` +
    `Check the 'Generate Report with AI' and current node outputs directly.`
  );
}

// Determine if the merged result is a complete HTML document or still a fragment.
// If it has no </body> or </html>, it's incomplete — destined for another merge 
// pass. In that case we pass it through WITHOUT auto-repair or validation throws,
// since any unclosed tags are expected and correct for a partial document.
let finalMerged = result.merged;
const isCompleteDocument = finalMerged.includes('</body>') || finalMerged.includes('</html>');

if (isCompleteDocument) {
  // Auto-repair: for any tag with MORE opens than closes, insert the missing 
  // closing tags before </body>. Safe because unclosed tags at end of a complete
  // document are always outermost wrappers left open by AI truncation.
  const tagsToRepair = ['td', 'tr', 'tbody', 'thead', 'table', 'div'];
  for (const tag of tagsToRepair) {
    const check = tagBalance(finalMerged, tag);
    if (check.diff > 0) {
      const missing = `</${tag}>\n`.repeat(check.diff);
      finalMerged = finalMerged.replace('</body>', missing + '</body>');
    }
  }

  // Re-check after repair — if still unbalanced, something genuinely broke
  const reChecks = ['div', 'table', 'tr', 'td', 'th', 'p', 'span'].map(t => ({
    tag: t, ...tagBalance(finalMerged, t)
  }));
  const stillBroken = reChecks.filter(c => !c.balanced);
  if (stillBroken.length > 0) {
    const broken = stillBroken
      .map(c => `${c.tag}: ${c.opens} open / ${c.closes} close (diff: ${c.diff})`)
      .join(', ');
    throw new Error(
      `MERGE PRODUCED UNBALANCED HTML (strategy: ${result.strategy}). ` +
      `Broken tags after auto-repair: ${broken}. Manual review required.`
    );
  }
} 
// If incomplete (no </body>): pass through as-is for next merge cycle.
// Unclosed tags are expected and intentional in a partial document.

// ---------- Fix <title> metadata ----------
// Always inject the current date into the <title> tag regardless of what
// the AI generated. Uses the n8n execution timestamp — always available,
// always correct — instead of trying to parse the HTML body, which fails
// whenever the AI uses a different div class name for the date.
const now = new Date();
const months = ['January','February','March','April','May','June',
                'July','August','September','October','November','December'];
const formattedDate = `${months[now.getMonth()]} ${now.getDate()}, ${now.getFullYear()}`;
const newTitle = `<title>ToKawa Roast Analysis Report — ${formattedDate}</title>`;

let finalHtml = finalMerged.replace(/<title>[^<]*<\/title>/, newTitle);

// Safety net: if no <title> tag exists at all, insert one into <head>
if (!finalHtml.includes('<title>')) {
  finalHtml = finalHtml.replace('<head>', `<head>\n${newTitle}`);
}

return [{
  json: {
    output: finalHtml,
    _merge_strategy: result.strategy,
    _merge_detail: result.detail
  }
}];
